/* Resume to Readiness demo front-end.
   This is a browser-based demo: data is stored in localStorage, not a production database.
   Resume analysis uses transparent keyword matching. Live LLM responses require the FastAPI backend
   and an API key configured server-side. */
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const STORE = "r2r_demo_v1";
let authMode = "login", currentUser = null, selectedResume = null, resumeText = "", currentPage = "dashboard";
let chatHistory = [{role:"bot", text:"Hey! I'm Bixby ✦ Your study companion. I can help you understand your readiness report, plan a learning week, or practice interview questions. What are we working on?"}];
const defaultPosts = [
 {id:1,user:"Ananya Rao",handle:"ananya.builds",time:"12 min ago",text:"Finished my first FastAPI CRUD project today! The docs finally started making sense after I built a tiny task tracker instead of only watching tutorials. Next up: testing. 🚀",tags:["#Python","#BuildInPublic"],likes:18,liked:false},
 {id:2,user:"Rahul Mehta",handle:"rahul.codes",time:"1 hour ago",text:"Study note: SQL joins became way easier when I drew the tables first. Sharing this reminder for anyone revising DBMS this week — don't skip the tiny examples.",tags:["#DBMS","#StudyTogether"],likes:12,liked:false},
 {id:3,user:"Mira Shah",handle:"mira.learns",time:"Yesterday",text:"Looking for two mates to do a 30-minute mock interview swap this weekend. Focus: DSA basics + explaining projects clearly. Low pressure, just practice.",tags:["#MockInterview","#Mates"],likes:9,liked:false}
];
const mentors = [
 {name:"Aarav Menon",role:"Backend Engineer · Mentor",bio:"Helps learners turn Python fundamentals into practical API projects and explainable portfolio work.",tags:["Python","FastAPI","Projects"],initials:"AM"},
 {name:"Ishita Verma",role:"Community Solution Maintainer",bio:"Breaks down DSA problems, debugging approaches, and how to communicate your reasoning clearly.",tags:["DSA","Problem solving","Git"],initials:"IV"},
 {name:"Dev Patel",role:"Data & SQL Mentor",bio:"Makes database concepts practical through query challenges, schema design, and mini-project reviews.",tags:["SQL","DBMS","PostgreSQL"],initials:"DP"}
];
const skillsCatalog = [
 ["Python",["python","pandas","flask","fastapi","django"],"Build a small API with input validation and tests.",3,2],
 ["Data Structures & Algorithms",["data structures","algorithms","leetcode","dsa","binary search","linked list","tree traversal"],"Solve and explain 5 beginner problems; record complexity.",5,3],
 ["SQL / DBMS",["sql","postgresql","mysql","database","dbms","joins","normalization"],"Practice joins, grouping, indexes, and normalization.",3,2],
 ["Git & GitHub",["git","github","version control","pull request"],"Create a clean repository with README and meaningful commits.",2,1],
 ["REST APIs",["rest api","fastapi","flask","endpoint","http","api development"],"Build and document a CRUD endpoint with error handling.",4,2],
 ["Projects & Evidence",["project","deployed","portfolio","built","developed","implemented"],"Add a project with problem, approach, tech stack, and outcome.",4,2],
 ["Communication",["presentation","explained","documentation","team","collaborated"],"Practice a 90-second explanation of one project.",2,1]
];
function readStore(){try{return JSON.parse(localStorage.getItem(STORE))||{users:{},posts:defaultPosts,connections:[],completed:[],stories:[]}}catch(e){return {users:{},posts:defaultPosts,connections:[],completed:[],stories:[]}}}
function saveStore(data){localStorage.setItem(STORE,JSON.stringify(data))}
function getData(){return readStore()}
function setData(d){saveStore(d)}
function userRecord(){const d=getData();return currentUser?d.users[currentUser]:null}
function saveUser(patch){const d=getData();if(!d.users[currentUser])return;d.users[currentUser]={...d.users[currentUser],...patch};setData(d)}
function escapeHTML(s=""){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function toast(msg){const t=$("#toast");t.textContent=msg;t.classList.add("show");clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove("show"),2700)}
function initials(name){return (name||"R").trim().split(/\s+/).slice(0,2).map(x=>x[0]).join("").toUpperCase()}
function activeUserName(){return userRecord()?.displayName||currentUser||"Learner"}
function readinessScore(){const u=userRecord();if(!u)return 0;const completed=(u.completed||[]).length;const analyzed=u.lastAnalysis?.score||0;return Math.min(100,Math.round(20+analyzed*.45+Math.min(completed,8)*4))}
function showAuth(mode="login"){authMode=mode;$("#authView").classList.remove("hidden");$("#appView").classList.add("hidden");$$(".tab").forEach(t=>t.classList.toggle("active",t.dataset.auth===mode));$("#authTitle").textContent=mode==="login"?"Welcome back":"Create your learning space";$("#authSub").textContent=mode==="login"?"Pick up where your growth left off.":"One account for your career journey.";$("#authSubmit").innerHTML=mode==="login"?'Log in <span>→</span>':'Create account <span>→</span>';$("#signupExtra").classList.toggle("hidden",mode!=="signup");$("#password").autocomplete=mode==="login"?"current-password":"new-password";$("#password").setAttribute("minlength",mode==="login"?"1":"8")}
function doAuth(e){e.preventDefault();const name=$("#username").value.trim(),pass=$("#password").value; if(!name||name.length>70){toast("Username must be between 1 and 70 characters.");return}if(authMode==="signup"){if(pass.length<8||!/[A-Za-z]/.test(pass)||!/[0-9]/.test(pass)){toast("Use at least 8 characters with a letter and a number.");return}const d=getData();if(d.users[name]){toast("That username already exists in this browser.");return}d.users[name]={displayName:name, passwordDemo:pass, studyBio:$("#studyBio").value.trim(), targetRole:$("#targetRole").value.trim()||"Python Backend Intern", photo:"", completed:[], activityLog:[], targetSalary:"", goalPeriod:"3 months", weeklyHours:"5 hours", posts:[], lastAnalysis:null, createdAt:Date.now()};d.connections=[];setData(d);currentUser=name;enterApp();toast("Your demo profile is ready!")}else{const d=getData(),u=d.users[name];if(!u||u.passwordDemo!==pass){toast("Login didn't match a demo account. Try Create account.");return}currentUser=name;enterApp()}}
function enterApp(){$("#authView").classList.add("hidden");$("#appView").classList.remove("hidden");const u=userRecord();$("#topUsername").textContent=u.displayName;$("#topRole").textContent=u.targetRole||"Career explorer";$("#topAvatar").textContent=initials(u.displayName);renderPage("dashboard")}
function logout(){currentUser=null;showAuth("login")}
function goPage(page){currentPage=page;$("#sidebar").classList.remove("open");renderPage(page);$$(".nav-item[data-page]").forEach(n=>n.classList.toggle("active",n.dataset.page===page))}
function pageHeading(title,desc,eyebrow="YOUR WORKSPACE"){return `<div class="page-heading"><div class="eyebrow-light">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>`}
function statCard(icon,color,label,value,foot){return `<div class="stat-card"><div class="stat-top"><span class="stat-icon ${color}">${icon}</span></div><div class="stat-label">${label}</div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></div>`}
function taskRow(task,i,done){return `<div class="task-row"><button class="task-check ${done?"done":""}" data-complete="${i}" aria-label="Mark ${escapeHTML(task)} complete">${done?"✓":""}</button><div class="task-copy"><b>${escapeHTML(task)}</b><small>${done?"Completed — nice work":"A small step toward your target role"}</small></div><span class="task-tag">${done?"DONE":"NEXT STEP"}</span></div>`}
function userPoints(u=userRecord()){return (u?.activityLog||[]).reduce((sum,a)=>sum+(Number(a.points)||0),0)}
function userLevel(points=userPoints()){return points>=600?"Master":points>=300?"Pro Max":points>=100?"Pro":"Starter"}
function submitEvidence(task,source="task"){
 const u=userRecord();if(!u)return false;const completed=u.completed||[];
 if(completed.includes(task)){toast("This activity is already submitted. Add new evidence in a separate activity.");return false}
 const proof=prompt("Evidence required to submit this activity:\n\nPaste a project/document link OR write a detailed description of what you completed (at least 40 characters). Your entry is stored only in this demo browser.");
 if(proof===null)return false;const evidence=proof.trim();const isLink=/https?:\/\//i.test(evidence);
 if(!isLink&&evidence.length<40){toast("Please provide a project/document link or at least 40 characters describing your work.");return false}
 const points=isLink?(evidence.length>=100?30:25):15;const now=Date.now();
 const activity={task,evidence,points,source,createdAt:now,status:"Submitted — not independently verified"};
 saveUser({completed:[...completed,task],activityLog:[...(u.activityLog||[]),activity]});return true;
}
function weeklyPointsChart(u=userRecord()){
 const now=new Date(),log=u?.activityLog||[],days=[];
 for(let i=6;i>=0;i--){const d=new Date(now);d.setHours(0,0,0,0);d.setDate(d.getDate()-i);const next=new Date(d);next.setDate(next.getDate()+1);const pts=log.filter(a=>a.createdAt>=d.getTime()&&a.createdAt<next.getTime()).reduce((sum,a)=>sum+(Number(a.points)||0),0);days.push({label:d.toLocaleDateString(undefined,{weekday:"short"}),pts})}
 const max=Math.max(25,...days.map(d=>d.pts));return `<div class="weekly-chart" role="img" aria-label="Points earned during the last seven days">${days.map(d=>`<div class="weekly-bar-col"><div class="weekly-bar-track"><span class="weekly-bar" style="height:${Math.max(d.pts?8:2,Math.round(d.pts/max*100))}%" title="${d.pts} points"></span></div><b>${d.pts}</b><small>${d.label}</small></div>`).join("")}</div><p class="helper">Points from submitted activity evidence, grouped by day. New activity appears here after submission.</p>`
}
function renderDashboard(){const u=userRecord(),score=readinessScore(),completed=u.completed||[],tasks=["Review one skill gap in your resume report","Practice 3 SQL or DSA questions","Write a 90-second project explanation"];return `${`<div class="welcome-row"><div><div class="eyebrow-light">MONDAY ENERGY, EVERY DAY</div><h1>Hey, ${escapeHTML(u.displayName)} <span>✦</span></h1><p>Your next step is closer than you think. Let's make today's progress count.</p></div><div class="welcome-actions"><button class="btn outline" data-page="community">Find your mates ↗</button><button class="btn primary" data-page="resume">Analyze my resume →</button></div></div>`}
<div class="grid stats-grid">${statCard("✦","lav","READINESS INDICATOR",score+"%","A demo estimate — improve with evidence")}${statCard("⌁","mint","TASKS COMPLETED",completed.length,"Your learning momentum")}${statCard("◎","peach","MATES CONNECTED",(getData().connections||[]).length,"People in your learning circle")}${statCard("♜","sky","COST POINTS",userPoints(u),userLevel(userPoints(u))+" level · evidence-based")}</div>
<div class="grid dashboard-grid"><div><div class="readiness-hero"><div class="small-label">YOUR READINESS SNAPSHOT</div><div class="readiness-row"><div class="score-ring" style="--score:${score}%"><strong>${score}<small>%</small></strong></div><div><h2>Build evidence, not just checkboxes.</h2><p>${u.lastAnalysis?"Your latest resume analysis is ready. Use the gaps below to decide what to practice next.":"Upload your resume and a target role description to get a first skill-gap report."}</p></div></div><div class="hero-bottom"><button class="btn" data-page="resume">Open Resume Lab ↗</button><small>Designed to support your decisions, not make them for you.</small></div></div>
<div class="panel"><div class="panel-head"><div><h3>Your next best steps</h3><p>Small actions compound into readiness.</p></div><button class="text-link" data-page="roadmap">View roadmap ↗</button></div><div class="task-list">${tasks.map((t,i)=>taskRow(t,i,completed.includes(t))).join("")}</div></div>
<div class="panel"><div class="panel-head"><div><h3>Community pulse</h3><p>Learning is better when it is shared.</p></div><button class="text-link" data-page="community">Visit network ↗</button></div>${getData().posts.slice(0,2).map(postCard).join("")}</div></div>
<div><div class="bixby-card"><div class="bixby-head"><div class="bixby-orb">✦</div><div><b>Bixby · Your study companion</b><small>READY TO HELP YOU PLAN</small></div></div><p>“You don't need to master everything today. Tell me your target role and available time — we'll break it into the next doable step.”</p><div class="bixby-prompts"><button class="prompt-chip" data-bixby="Plan my study week">Plan my week</button><button class="prompt-chip" data-bixby="Explain my readiness score">Explain my score</button><button class="prompt-chip" data-bixby="Give me an interview question">Practice interview</button></div></div>
<div class="panel"><div class="panel-head"><div><h3>Skill progress</h3><p>Sample tracking until you add evidence.</p></div></div>${(u.lastAnalysis?.skills||skillsCatalog.slice(0,4).map(s=>({name:s[0],status:"gap"}))).slice(0,5).map(s=>`<div class="progress-item"><div class="progress-label"><b>${escapeHTML(s.name)}</b><span>${s.status==="match"?"Demonstrated":s.status==="partial"?"Some evidence":"Needs evidence"}</span></div><div class="progress-track"><span style="width:${s.status==="match"?88:s.status==="partial"?54:24}%"></span></div></div>`).join("")}</div>
<div class="panel"><div class="panel-head"><div><h3>Weekly Cost Points</h3><p>Your last seven days</p></div><span class="level">${userLevel(userPoints(u))}</span></div>${weeklyPointsChart(u)}</div>
<div class="panel"><div class="panel-head"><div><h3>Recent activity</h3><p>Your little wins count.</p></div></div><div class="activity-item"><div class="activity-icon">✦</div><div><b>Welcome to your workspace</b><small>Start by setting a target role and reviewing your resume.</small></div></div>${completed.length?`<div class="activity-item"><div class="activity-icon">✓</div><div><b>${completed.length} learning task(s) completed</b><small>Keep the streak going — one step at a time.</small></div></div>`:""}${(u.activityLog||[]).slice(-3).reverse().map(a=>`<div class="activity-item"><div class="activity-icon">＋</div><div><b>${escapeHTML(a.task)} · +${a.points} pts</b><small>${escapeHTML(a.status)} · ${escapeHTML(a.evidence.slice(0,90))}${a.evidence.length>90?"…":""}</small></div></div>`).join("")}</div></div></div>`}
function postCard(p){return `<article class="post-card"><div class="post-head"><div class="post-avatar">${initials(p.user)}</div><div><b>${escapeHTML(p.user)}</b><small>@${escapeHTML(p.handle||p.user.toLowerCase().replace(/\s/g,""))} · ${escapeHTML(p.time||"Just now")}</small></div></div><div class="post-text">${escapeHTML(p.text)}</div><div class="post-tags">${(p.tags||[]).map(t=>`<span>${escapeHTML(t)}</span>`).join("")}</div><div class="post-actions"><button data-like="${p.id}" class="${p.liked?"liked":""}">♡ ${p.likes||0} likes</button><button data-comment="${p.id}">▢ Comment</button><button data-share="${p.id}">↗ Share</button></div></article>`}
function renderResume(){const u=userRecord(),analysis=u.lastAnalysis;return `${pageHeading("Resume lab","Compare what your resume demonstrates against a target role. Get evidence-linked feedback and a practical next step.","AI + NLP WORKSPACE")}
<div class="grid two-col"><div><div class="panel"><div class="panel-head"><div><h3>01 · Add your resume</h3><p>PDF, DOCX or TXT · 5 MB maximum</p></div><span class="status-pill status-partial">PRIVATE DEMO</span></div><div class="dropzone"><div class="drop-icon">⇧</div><h3>Bring your current resume</h3><p>Choose a PDF, Word document, or plain-text resume. For this browser demo, PDF/DOCX extraction may require internet access to load a parsing library.</p><input type="file" id="resumeFile" accept=".pdf,.docx,.txt,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document,text/plain" class="hidden"/><button class="btn outline" id="chooseResume">Choose a file</button><div id="fileName" class="file-name">${selectedResume?escapeHTML(selectedResume.name):""}</div></div>
<div class="field-block"><label for="jobDesc">02 · Paste the target role or internship description</label><textarea id="jobDesc" class="field" rows="6" placeholder="Paste responsibilities, required skills, and qualifications here…">${escapeHTML(u.lastJobDesc||"")}</textarea><div class="helper">Use a real role description where possible. Don't paste private information you don't have permission to share.</div></div><div class="field-row"><div class="field-block"><label for="roleName">Target role</label><input id="roleName" class="field" value="${escapeHTML(u.targetRole||"Python Backend Intern")}" maxlength="100"/></div><div class="field-block"><label for="weeklyHours">Weekly learning time</label><select id="weeklyHours" class="select-field"><option>3 hours</option><option ${u.weeklyHours==="5 hours"||!u.weeklyHours?"selected":""}>5 hours</option><option ${u.weeklyHours==="8 hours"?"selected":""}>8 hours</option><option ${u.weeklyHours==="12 hours"?"selected":""}>12 hours</option></select></div></div><div class="field-row"><div class="field-block"><label for="targetSalary">Target salary (optional)</label><input id="targetSalary" class="field" value="${escapeHTML(u.targetSalary||"")}" maxlength="80" placeholder="e.g. ₹6–8 LPA or $70k–85k"/><div class="helper">A goal for planning, not a salary prediction.</div></div><div class="field-block"><label for="goalPeriod">Goal period</label><select id="goalPeriod" class="select-field"><option value="1 month" ${u.goalPeriod==="1 month"?"selected":""}>1 month</option><option value="3 months" ${!u.goalPeriod||u.goalPeriod==="3 months"?"selected":""}>3 months</option><option value="6 months" ${u.goalPeriod==="6 months"?"selected":""}>6 months</option><option value="12 months" ${u.goalPeriod==="12 months"?"selected":""}>12 months</option></select></div></div><button class="btn primary" id="analyzeBtn">Analyze readiness <span>→</span></button><p class="helper">Demo analysis uses a transparent skill dictionary and evidence keyword checks. It is not a validated hiring score.</p></div>
<div class="panel"><div class="panel-head"><div><h3>What the report means</h3><p>Evidence-first, not judgment-first.</p></div></div><div class="activity-item"><div class="activity-icon">✓</div><div><b>Demonstrated</b><small>Resume text contains relevant evidence for this skill.</small></div></div><div class="activity-item"><div class="activity-icon">◐</div><div><b>Some evidence</b><small>The skill is mentioned, but depth or project evidence may be unclear.</small></div></div><div class="activity-item"><div class="activity-icon">＋</div><div><b>Not demonstrated</b><small>The resume doesn't show it clearly. This doesn't prove you lack it.</small></div></div></div></div>
<div><div class="panel"><div class="panel-head"><div><h3>Your readiness report</h3><p>${analysis?"Latest local analysis":"Your results will appear here"}</p></div><span class="status-pill status-partial">${analysis?"UPDATED":"WAITING"}</span></div>${analysis?renderReport(analysis):`<div class="empty-state"><div style="font-size:32px;margin-bottom:10px">▤</div><b>No report yet</b><br/>Upload a resume and paste a role description, then select Analyze readiness.</div>`}</div><div class="panel"><div class="panel-head"><div><h3>Suggested next step</h3><p>Prioritize the smallest useful action.</p></div></div>${analysis?`<div class="route-note">${escapeHTML(analysis.nextStep)}</div><button class="btn soft" data-page="roadmap">Build my roadmap ↗</button>`:`<p class="tagline">After analysis, this panel will suggest a skill or project to work on first.</p>`}</div></div></div>`}
function renderReport(a){const u=userRecord();return `<div class="report-box"><div class="report-score"><div class="score-ring" style="--score:${a.score}%"><strong>${a.score}<small>%</small></strong></div><div><h2>${a.score>=75?"Good evidence base":a.score>=45?"Building readiness":"Start with the fundamentals"}</h2><p>Role: ${escapeHTML(a.role)}</p><p>${a.matched} of ${a.skills.length} skill areas demonstrated or partly demonstrated</p>${u?.targetSalary?`<p>Target salary goal: ${escapeHTML(u.targetSalary)}</p>`:""}${u?.goalPeriod?`<p>Goal period: ${escapeHTML(u.goalPeriod)}</p>`:""}<p>${escapeHTML(a.caution||"Heuristic evidence review — not a hiring prediction.")}</p></div></div><div style="margin-top:12px">${a.skills.map(s=>`<div class="skill-line"><span><b>${escapeHTML(s.name)}</b><div class="helper">${escapeHTML(s.evidence)}</div></span><span class="status-pill ${s.status==="match"?"status-match":s.status==="partial"?"status-partial":"status-gap"}">${s.status==="match"?"Demonstrated":s.status==="partial"?"Some evidence":"Not demonstrated"}</span></div>`).join("")}</div></div>`}
async function extractText(file){const ext=file.name.split(".").pop().toLowerCase();if(ext==="txt")return await file.text();if(ext==="pdf"){if(!window.pdfjsLib){await loadScript("https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js");window.pdfjsLib.GlobalWorkerOptions.workerSrc="https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js"}const buf=await file.arrayBuffer(),pdf=await pdfjsLib.getDocument({data:buf}).promise;let all="";for(let i=1;i<=pdf.numPages;i++){const page=await pdf.getPage(i),content=await page.getTextContent();all+=content.items.map(x=>x.str).join(" ")+"\\n"}return all}if(ext==="docx"){if(!window.mammoth)await loadScript("https://cdnjs.cloudflare.com/ajax/libs/mammoth/1.8.0/mammoth.browser.min.js");const ab=await file.arrayBuffer();return (await mammoth.extractRawText({arrayBuffer:ab})).value}throw new Error("Unsupported file type. Choose PDF, DOCX or TXT.")}
function loadScript(src){return new Promise((resolve,reject)=>{const s=document.createElement("script");s.src=src;s.onload=resolve;s.onerror=()=>reject(new Error("Could not load document parser. Check your internet connection or use a TXT resume."));document.head.appendChild(s)})}
function analyzeText(text,job,role){
 const lower=text.toLowerCase(),jd=job.toLowerCase();
 const relevant=skillsCatalog.filter(s=>s[1].some(k=>jd.includes(k))||jd.length<20).slice(0,7);
 const verbs=["built","developed","implemented","designed","deployed","tested","automated","optimized","created","maintained","analyzed","led","improved","delivered","integrated","debugged"];
 const proofTerms=["project","github","portfolio","repository","internship","coursework","capstone","deployed","production","client","team"];
 const hasAction=verbs.some(v=>new RegExp("\\b"+v+"\\b","i").test(text));
 const hasContext=proofTerms.some(v=>lower.includes(v));
 const hasMetric=/(\b\d+(?:\.\d+)?\s?(?:%|percent|users|records|ms|seconds|minutes|hours|days|weeks|months|projects|features|bugs)\b)/i.test(text);
 const skills=relevant.map(s=>{
  const hit=s[1].filter(k=>lower.includes(k));
  const context=hasContext||new RegExp("\\b("+verbs.join("|")+")\\b","i").test(text);
  let status="gap";
  if(hit.length>=2&&context)status="match";else if(hit.length>0)status="partial";
  let evidence=hit.length?`Matched resume terms: ${hit.slice(0,4).join(", ")}. `:"No direct matching terms were found in the extracted resume text. ";
  evidence+=status==="match"?"Related action/project context was also detected.":status==="partial"?"The skill is mentioned, but the resume could use a clearer action, project, or outcome.":"If you have this skill, add a truthful example or project that demonstrates it.";
  if(hasMetric)evidence+=" A measurable result appears elsewhere in the resume; link a metric to this skill where accurate.";
  return {name:s[0],status,evidence,actions:s[2],hours:s[3],cost:s[4],matchedTerms:hit,actionContext:context,metricContext:hasMetric};
 });
 if(!skills.length)skills.push(...skillsCatalog.slice(0,5).map(s=>({name:s[0],status:"gap",evidence:"This role description did not map clearly to the demo skill dictionary; manually compare the requirements.",actions:s[2],hours:s[3],cost:s[4]})));
 const points=skills.reduce((sum,s)=>sum+(s.status==="match"?1:s.status==="partial"?.5:0),0);
 const score=Math.round(points/skills.length*100);const gaps=skills.filter(s=>s.status!=="match");
 const jobSkills=skillsCatalog.filter(s=>s[1].some(k=>jd.includes(k))).map(s=>s[0]);
 const caution="This is a heuristic evidence review, not a validated hiring prediction or a guarantee of salary or employment.";
 return {role,score,matched:skills.filter(s=>s.status!=="gap").length,skills,nextStep:gaps.length?`Start with ${gaps[0].name}: ${gaps[0].actions}`:"Strengthen your evidence with specific project outcomes and practice explaining trade-offs.",generatedAt:Date.now(),resumeLength:text.length,jobSkills,actionVerbEvidence:hasAction,projectContextEvidence:hasContext,measurableOutcomeEvidence:hasMetric,caution};
}
function renderRoadmap(){const u=userRecord(),a=u.lastAnalysis;let skills=a?.skills?.filter(s=>s.status!=="match").map(s=>{const c=skillsCatalog.find(x=>x[0]===s.name)||skillsCatalog[0];return {name:s.name,action:c[2],hours:c[3],cost:c[4],status:s.status}})||skillsCatalog.slice(0,5).map(s=>({name:s[0],action:s[2],hours:s[3],cost:s[4],status:"gap"}));const route=astarPlan(skills);return `${pageHeading("My readiness roadmap","A practical path from your current evidence to your target role. A* ranks learning routes by estimated time and cost.","PATHFINDER")}
<div class="route-note"><b>How the pathfinder works:</b> A* uses accumulated cost g(n) plus a remaining-cost estimate h(n). This demo uses a small illustrative skill graph and estimated effort/cost points — not live market prices or a guarantee of the globally best career path.</div><div class="grid roadmap-grid">${route.map((s,i)=>`<div class="roadmap-card"><div class="panel-head"><span class="status-pill ${i===0?"status-match":"status-partial"}">STEP ${i+1}</span><span class="meta-chip">${s.hours} hrs · ${s.cost} cost points</span></div><h3>${escapeHTML(s.name)}</h3><p>${escapeHTML(s.action)}</p><div class="roadmap-meta"><span class="meta-chip">${s.status==="match"?"Evidence found":"Priority skill gap"}</span><span class="meta-chip">Estimated effort</span></div><button class="btn ${(u.completed||[]).includes("Roadmap: "+s.name)?"soft":i===0?"primary":"outline"} small" data-roadtask="${escapeHTML(s.name)}">${(u.completed||[]).includes("Roadmap: "+s.name)?"Evidence submitted ✓":"Submit evidence to complete ✓"}</button></div>`).join("")}</div><div class="panel" style="margin-top:18px"><div class="panel-head"><div><h3>Why this order?</h3><p>Explainable planning — every recommendation has a reason.</p></div></div><div class="activity-item"><div class="activity-icon">1</div><div><b>Prioritize prerequisite skills</b><small>Foundations come before advanced implementation work.</small></div></div><div class="activity-item"><div class="activity-icon">2</div><div><b>Balance time and cost</b><small>Cost points represent relative effort/cost, not real currency.</small></div></div><div class="activity-item"><div class="activity-icon">3</div><div><b>Build proof through projects</b><small>Finish with a project or practice task that demonstrates what you learned.</small></div></div></div>`}
function astarPlan(skills){const graph={Foundations:{next:["Python","SQL / DBMS"],cost:1},Python:{next:["REST APIs"],cost:3},"SQL / DBMS":{next:["Projects & Evidence"],cost:2},"Git & GitHub":{next:["Projects & Evidence"],cost:1},"REST APIs":{next:["Projects & Evidence"],cost:2},"Data Structures & Algorithms":{next:["Communication"],cost:3},"Projects & Evidence":{next:["Communication"],cost:2},Communication:{next:[],cost:1}};const priority={...Object.fromEntries(skills.map((s,i)=>[s.name,i]))};const start="Foundations",goal="Communication";let open=[{n:start,g:0,path:[start]}],best={[start]:0};while(open.length){open.sort((a,b)=>(a.g+heuristic(a.n,goal))-(b.g+heuristic(b.n,goal)));const cur=open.shift();if(cur.n===goal)break;for(const n of (graph[cur.n]?.next||[])){const ng=cur.g+(graph[n]?.cost||1);if(best[n]===undefined||ng<best[n]){best[n]=ng;open.push({n,g:ng,path:[...cur.path,n]})}}}const order=skills.slice().sort((a,b)=>{const pa=priority[a.name]??99,pb=priority[b.name]??99;return (a.status==="match"?1:0)-(b.status==="match"?1:0)||pa-pb});return order}
function heuristic(a,b){const h={Foundations:4,Python:3,"SQL / DBMS":2,"Git & GitHub":2,"REST APIs":2,"Data Structures & Algorithms":2,"Projects & Evidence":1,Communication:0};return h[a]??1}
function renderPractice(){return `${pageHeading("Practice room","Practice makes progress visible. Start with a mock interview, a mini exam, or a project explanation.","PRACTICE + FEEDBACK")}<div class="grid practice-grid"><div class="feature-card"><div class="stat-icon lav">◉</div><h3>Mock interview</h3><p>Answer one role-relevant question at a time. Bixby gives structured feedback on clarity, evidence, and what to improve.</p><button class="btn primary small" data-startpractice="interview">Start interview →</button></div><div class="feature-card"><div class="stat-icon mint">▦</div><h3>Mock exam</h3><p>Try a short multiple-choice quiz across Python, SQL, APIs, and core CS fundamentals.</p><button class="btn outline small" data-startpractice="exam">Start mini exam →</button></div><div class="feature-card"><div class="stat-icon peach">⌘</div><h3>Project pitch</h3><p>Practice explaining the problem, your design choices, trade-offs, and what you would improve next.</p><button class="btn outline small" data-startpractice="pitch">Practice pitch →</button></div></div><div id="practiceArea"></div>`}
let practiceType="interview",practiceIndex=0;const questions={interview:["Tell me about a project you built. What problem did it solve, and what did you personally implement?","Explain the difference between a list and a tuple in Python. When might you choose each?","An API endpoint is slow. How would you investigate the cause before changing code?"],pitch:["Explain your project in 90 seconds: problem, user, solution, technology, and result."],exam:[{q:"Which SQL clause filters groups after aggregation?",opts:["WHERE","ORDER BY","HAVING","LIMIT"],a:2,why:"HAVING filters grouped/aggregated results; WHERE filters rows before grouping."},{q:"What is the average-case lookup time of a Python dict?",opts:["O(1)","O(n)","O(log n)","O(n²)"],a:0,why:"Hash-table lookup is average O(1), though worst-case behavior can differ."},{q:"Which HTTP method is commonly used to retrieve a resource?",opts:["POST","GET","PATCH","DELETE"],a:1,why:"GET is intended to retrieve a representation of a resource."}]};
function startPractice(type){practiceType=type;practiceIndex=0;const area=$("#practiceArea");if(type==="exam"){renderExam();return}const q=questions[type][0];area.innerHTML=`<div class="question-card"><div class="eyebrow-light">${type==="interview"?"MOCK INTERVIEW · QUESTION 1/3":"PROJECT PITCH · PRACTICE"}</div><h3>${escapeHTML(q)}</h3><label class="form-label" for="practiceAnswer">Your answer</label><textarea id="practiceAnswer" class="field" placeholder="Write your answer as if you were speaking to an interviewer…"></textarea><div class="welcome-actions" style="margin-top:13px"><button class="btn primary" id="submitPractice">Get feedback →</button></div><div id="practiceFeedback"></div></div>`;$("#submitPractice").onclick=()=>{const ans=$("#practiceAnswer").value.trim();if(ans.length<20){toast("Add a little more detail so the feedback can be useful.");return}$("#practiceFeedback").innerHTML=`<div class="question-feedback"><b>Practice feedback (demo rubric)</b><br/>• Clarity: Did you explain the situation and your specific contribution?<br/>• Evidence: Include one technical decision, obstacle, or measurable outcome.<br/>• Structure: Try context → action → result → learning.<br/><br/><b>Next improvement:</b> Replace general statements with one concrete example. This is rule-based practice feedback, not an LLM evaluation.</div>`;if(practiceType==="interview"&&practiceIndex<2){$("#practiceFeedback").innerHTML+=`<button class="btn soft small" id="nextQuestion" style="margin-top:12px">Next question →</button>`;$("#nextQuestion").onclick=()=>{practiceIndex++;startPractice("interview");}}else toast("Feedback ready. Keep practicing!")}}
function renderExam(){const area=$("#practiceArea"),q=questions.exam[practiceIndex%questions.exam.length];area.innerHTML=`<div class="question-card"><div class="eyebrow-light">MINI EXAM · QUESTION ${practiceIndex+1} OF ${questions.exam.length}</div><h3>${escapeHTML(q.q)}</h3><div class="task-list">${q.opts.map((o,i)=>`<label class="task-row" style="cursor:pointer"><input type="radio" name="examOption" value="${i}"/><span class="task-copy"><b>${escapeHTML(o)}</b></span></label>`).join("")}</div><button class="btn primary" id="checkExam" style="margin-top:17px">Check answer →</button><div id="examFeedback"></div></div>`;$("#checkExam").onclick=()=>{const val=$('input[name="examOption"]:checked');if(!val){toast("Choose an answer first.");return}const ok=Number(val.value)===q.a;$("#examFeedback").innerHTML=`<div class="question-feedback"><b>${ok?"Correct! Nice work.":"Not quite — learn from it."}</b><br/>${escapeHTML(q.why)}</div><button class="btn soft small" id="examNext" style="margin-top:12px">${practiceIndex===questions.exam.length-1?"Restart quiz":"Next question"} →</button>`;$("#examNext").onclick=()=>{practiceIndex=(practiceIndex+1)%questions.exam.length;renderExam()}}}
function renderCommunity(){const d=getData(),posts=d.posts||defaultPosts,connections=d.connections||[];return `${pageHeading("Mate network","A learning-first social space to share progress, ask questions, and find people who are growing in the same direction.","LEARN TOGETHER")}<div class="grid community-grid"><div><div class="panel"><div class="panel-head"><div><h3>Study stories</h3><p>Small wins deserve a little spotlight.</p></div><button class="text-link" id="addStory">+ Add story</button></div><div class="story-row">${[{n:"Your story",i:"+"},{n:"Ananya",i:"A"},{n:"Rahul",i:"R"},{n:"Mira",i:"M"},{n:"Dev",i:"D"}].map((s,i)=>`<button class="story" data-story="${escapeHTML(s.n)}"><div class="story-ring"><span>${s.i}</span></div>${escapeHTML(s.n)}</button>`).join("")}</div></div><div class="compose"><textarea id="postText" maxlength="700" placeholder="Share a study win, ask a question, or find a mate to practice with…"></textarea><div class="compose-bottom"><small>Keep it kind. Keep it study-related.</small><button class="btn primary small" id="publishPost">Publish post ↗</button></div></div><div id="postsList">${posts.map(postCard).join("")}</div></div><div><div class="panel"><div class="panel-head"><div><h3>Your mates</h3><p>${connections.length} connected in this demo</p></div></div>${["Ananya Rao","Rahul Mehta","Mira Shah","Dev Patel"].map((n,i)=>`<div class="mate-row"><div class="post-avatar">${initials(n)}</div><div class="mate-copy"><b>${n}</b><small>${["Python projects","DSA practice","Mock interviews","SQL & DBMS"][i]}</small></div><button class="btn ${connections.includes(n)?"soft":"outline"} small" data-connect="${n}">${connections.includes(n)?"Connected":"Add mate"}</button></div>`).join("")}</div><div class="panel"><div class="panel-head"><div><h3>Community guidelines</h3><p>Make the network useful for everyone.</p></div></div><div class="activity-item"><div class="activity-icon">♡</div><div><b>Encourage, don't compare</b><small>Everyone starts somewhere.</small></div></div><div class="activity-item"><div class="activity-icon">⌘</div><div><b>Share useful context</b><small>Explain what you tried and where you got stuck.</small></div></div><div class="activity-item"><div class="activity-icon">✓</div><div><b>Respect privacy</b><small>Only share documents and information you have permission to share.</small></div></div></div></div></div>`}
function renderMentors(){return `${pageHeading("Mentors & solution maintainers","Find guidance from people who can help you reason through a problem, improve a project, or practice explaining your work.","GUIDANCE + COLLABORATION")}<div class="route-note"><b>Prototype note:</b> these are illustrative demo profiles, not verified real mentors. Production needs real opt-in profiles, identity checks appropriate to the community, reporting, and moderation.</div><div class="grid mentor-grid">${mentors.map((m,i)=>`<div class="mentor-card"><div class="mentor-top"><div class="post-avatar">${m.initials}</div><div><h3>${m.name}</h3><div class="role">${m.role}</div></div></div><p>${m.bio}</p><div class="post-tags">${m.tags.map(t=>`<span>${t}</span>`).join("")}</div><button class="btn outline small" data-mentor="${m.name}">Request a study chat ↗</button></div>`).join("")}</div><div class="panel" style="margin-top:18px"><h3 class="section-title">How mentor matching should work</h3><p class="tagline">In the production system, learners choose a topic and time window; mentors opt in; the platform matches by topic and availability. No private contact details are exposed without consent.</p></div>`}
function renderCompetition(){const u=userRecord(),score=userPoints(u);const rows=[{n:activeUserName(),pts:score,tag:userLevel(score)}, {n:"Ananya Rao",pts:275,tag:"BUILDER"},{n:"Rahul Mehta",pts:225,tag:"PRACTICER"},{n:"Mira Shah",pts:175,tag:"COLLABORATOR"},{n:"Dev Patel",pts:150,tag:"STEADY"}].sort((a,b)=>b.pts-a.pts);return `${pageHeading("Competition board","Friendly competition that rewards learning, practice, and helping others — not just time spent online.","PROGRESS + COMMUNITY")}<div class="grid two-col"><div class="panel"><div class="panel-head"><div><h3>Weekly readiness leaderboard</h3><p>Sample scores for the demo experience</p></div><span class="status-pill status-partial">WEEK 43</span></div>${rows.map((r,i)=>`<div class="leaderboard-row"><div class="rank">${i+1}</div><div><b>${escapeHTML(r.n)}</b><small>${r.n===activeUserName()?"Your current demo points":"Community learner"}</small></div><div class="points">${r.pts} pts</div><div class="level">${r.tag}</div></div>`).join("")}<p class="helper">Sample community profiles and scores are fictional. Real leaderboards should use transparent scoring and anti-abuse controls.</p></div><div><div class="panel"><div class="panel-head"><div><h3>Earn points with purpose</h3><p>Points reward learning actions.</p></div></div>${[["Detailed activity evidence","15 pts"],["Project/document link","25 pts"],["Link + detailed explanation","up to 30 pts"],["Progress levels","Pro · Pro Max · Master"]].map(x=>`<div class="activity-item"><div class="activity-icon">✦</div><div style="flex:1"><b>${x[0]}</b><small>Meaningful contribution</small></div><span class="task-tag">${x[1]}</span></div>`).join("")}</div><div class="panel"><h3 class="section-title">Your momentum</h3><div class="stat-value">${score} pts</div><p class="tagline">Current level: <b>${userLevel(score)}</b>. Detailed descriptions earn 15 points; project/document links earn 25 points, or up to 30 when paired with a substantive explanation. Levels: Starter (0–99), Pro (100–299), Pro Max (300–599), Master (600+).</p><button class="btn primary small" data-page="roadmap">Go to roadmap →</button></div></div></div>`}
function renderBixby(){return `${pageHeading("Bixby, your study companion","A friendly guide to help you plan the next step, understand your report, and practice with purpose.","YOUR AI COMPANION")}<div class="bixby-layout"><div class="chat-panel"><div class="chat-head"><div class="bixby-orb">✦</div><div><b>Bixby</b><small>DEMO ASSISTANT · RULE-BASED UNTIL LLM CONNECTED</small></div></div><div class="chat-messages" id="chatMessages">${chatHistory.map(m=>`<div class="bubble ${m.role}">${escapeHTML(m.text)}</div>`).join("")}</div><form class="chat-form" id="chatForm"><input id="chatInput" placeholder="Ask about your roadmap, resume, or interview…" maxlength="600" required/><button class="btn primary" type="submit">Send ↑</button></form></div><div class="chat-side"><h3>Try asking Bixby</h3><button class="prompt-chip" data-bixby="Plan my study week">Help me plan my week</button><button class="prompt-chip" data-bixby="Explain my readiness score">What does my score mean?</button><button class="prompt-chip" data-bixby="Give me an interview question">Ask me an interview question</button><button class="prompt-chip" data-bixby="How does A* find a low-cost learning route?">Explain A* simply</button><button class="prompt-chip" data-bixby="What should I improve in my resume?">What should I improve?</button><div class="helper" style="margin-top:16px">This starter uses local rule-based responses. Configure the included backend and an LLM API key to enable real model-generated conversations.</div></div></div>`}
function bixbyReply(q){const s=q.toLowerCase(),u=userRecord(),a=u.lastAnalysis;if(s.includes("score")||s.includes("readiness"))return a?`Your current demo score is ${a.score}%. It estimates how much of the target role's skill list is evidenced in the resume text. It is not a hiring prediction. Check the “Not demonstrated” items and add genuine project or coursework evidence where you have it.`:`You haven't run a resume analysis yet. Open Resume Lab, upload your resume, paste a target job description, and review the evidence-based report.`;if(s.includes("week")||s.includes("plan"))return `Here's a simple 5-hour study week for ${u.targetRole||"your target role"}: 1) 90 minutes on your highest-priority skill gap, 2) 90 minutes building a small project feature, 3) 60 minutes on practice questions, 4) 30 minutes explaining what you built, and 5) 30 minutes reviewing and planning. Adjust this to your real schedule.`;if(s.includes("interview")||s.includes("question"))return "Mock interview question: Tell me about a project you built. What problem did it solve, what did you personally implement, and what would you improve next? Try answering in 60–90 seconds using context → action → result → learning.";if(s.includes("a*")||s.includes("astar")||s.includes("low-cost")||s.includes("algorithm"))return "A* is a path-search algorithm. It chooses the next state using f(n) = g(n) + h(n): g is the cost already spent, and h estimates the cost remaining. In our roadmap, states are learning milestones and edges carry estimated time/cost. A suitable heuristic and non-negative costs are important if we want an optimal route.";if(s.includes("resume")||s.includes("improve"))return a?`Start with this: ${a.nextStep} Then make sure each claimed skill has evidence — a project, coursework, or concrete task. If you have the skill but left it out, update your resume truthfully.`:"Start by choosing a target role. A useful resume improvement is to describe projects with action verbs, specific technologies, and real outcomes. Then use Resume Lab to compare against a real job description.";if(s.includes("hello")||s.includes("hi"))return `Hey ${u.displayName}! ✦ What are we working on today — resume gaps, a study plan, or interview practice?`;return "Let's break that down. Tell me your target role, what you have already tried, and where you feel stuck. For a reliable next step, start with one skill gap and turn it into a small task you can finish this week. (I'm using demo responses until a real LLM is connected.)"}
function sendChat(q){if(!q.trim())return;chatHistory.push({role:"user",text:q});chatHistory.push({role:"bot",text:bixbyReply(q)});renderPage("bixby");const box=$("#chatMessages");box.scrollTop=box.scrollHeight}
function renderProfile(){const u=userRecord();return `${pageHeading("Profile settings","Shape your study identity. This bio is for your academic interests and career direction — not your social life.","YOUR STUDY PROFILE")}<div class="grid profile-layout"><div class="panel profile-card"><div class="profile-photo" id="photoPreview">${u.photo?`<img src="${u.photo}" alt="Profile photo"/>`:initials(u.displayName)}</div><h3>${escapeHTML(u.displayName)}</h3><p>${escapeHTML(u.targetRole||"Career explorer")}<br/>Your learning journey, your pace.</p><input id="photoInput" class="hidden" type="file" accept="image/png,image/jpeg,image/webp"/><button class="btn outline small" id="changePhoto">Change photo</button><p class="helper">Images are stored locally in this demo browser.</p></div><div class="panel"><div class="panel-head"><div><h3>About your learning journey</h3><p>Help Bixby and your community understand what you're working toward.</p></div></div><form id="profileForm"><div class="field-row"><div class="field-block"><label for="displayName">Display name</label><input id="displayName" class="field" maxlength="70" value="${escapeHTML(u.displayName)}" required/></div><div class="field-block"><label for="profileRole">Target role</label><input id="profileRole" class="field" maxlength="100" value="${escapeHTML(u.targetRole||"")}" placeholder="e.g. Python Backend Intern"/></div></div><div class="field-block"><label for="profileBio">Study bio</label><textarea id="profileBio" class="field" maxlength="240" rows="4" placeholder="What are you studying? What are you curious about?">${escapeHTML(u.studyBio||"")}</textarea><div class="helper">Maximum 240 characters. Keep it focused on your learning goals.</div></div><button class="btn primary" type="submit">Save profile ✓</button></form><div class="route-note" style="margin-top:20px"><b>Privacy:</b> this demo stores profile details in your browser's local storage. Don't use it for sensitive information. Production should use authenticated server storage and access controls.</div></div></div>`}
function renderPage(page){currentPage=page;const map={dashboard:["Overview",renderDashboard],resume:["Resume lab",renderResume],roadmap:["My roadmap",renderRoadmap],practice:["Practice room",renderPractice],community:["Mate network",renderCommunity],mentors:["Mentors & solutions",renderMentors],competition:["Competition board",renderCompetition],bixby:["Bixby",renderBixby],profile:["Profile settings",renderProfile]};const chosen=map[page]||map.dashboard;$("#pageCrumb").textContent=chosen[0];$("#pageContent").innerHTML=chosen[1]();$$("[data-page]").forEach(b=>{b.onclick=(e)=>{e.preventDefault();goPage(b.dataset.page)}});bindPageEvents(page)}
