if(page==="roadmap")$$("[data-roadtask]").forEach(b=>b.onclick=()=>{const task="Roadmap: "+b.dataset.roadtask;if(submitEvidence(task,"roadmap")){renderPage("roadmap");toast("Evidence submitted — Cost Points awarded. Verification is not automated in this demo.")}});
